        if (!line) return;
        if (line === 'save') { writeJson({ t: 'saved', ok: engine.saveGame() }); return; }
        if (line === 'frame') { writeJson(engine.buildFrame()); return; }
        if (line === 'quit' || line === 'exit') { engine.saveGame(); process.exit(0); return; }
